function report=run_representative_bridge()
% Fresh5-stage controlled bridge; no ablations, fit, OPF or observed-flow input.
root=fileparts(fileparts(fileparts(fileparts(mfilename('fullpath')))));
addpath(fullfile(root,'System Matpower Format'));
addpath(fullfile(root,'scripts','nygrid_2025_acpf_profile_audit','acpf'));
out=fullfile(root,'output','nygrid_2025_centraleast_diagnosis','experiments','representative_bridge');if ~isfolder(out),mkdir(out);end
archive=load(fullfile(fileparts(out),'archived_DC_reference.mat'));
hours=[archive.primary_hours(:)' archive.additional_diagnostic_extremes(:)'];hours=unique(hours,'stable');checks=struct([]);
dcopt=mpoption('model','DC','verbose',0,'out.all',0,'exp.use_legacy_core',1);
acopt=mpoption('model','AC','verbose',0,'out.all',0,'pf.alg','NR','pf.nr.max_it',50,'pf.tol',1e-10,'pf.enforce_q_lims',0,'exp.use_legacy_core',1);
start=tic;
for h=hours
    t=tic;prior=npcc_nygrid_2025_dover_dc(h,'bounded','x_nominal');detailed=npcc_nygrid_2025_ac(h);full=restore_full_DC_parent(prior,root);input_seconds=toc(t);
    assert(isequal(prior.gen(:,[1 2 8 9 10]),detailed.gen(:,[1 2 8 9 10]))&&isequal(prior.dcline,detailed.dcline));
    [ok,ix]=ismember(prior.bus(:,1),detailed.bus(:,1));assert(all(ok));
    assert(isequal(prior.bus(:,3:4),detailed.bus(ix,3:4))&&all(detailed.bus(~ismember(detailed.bus(:,1),prior.bus(:,1)),3:4)==0,'all'));
    t=tic;slim_dc=rundcpf(prior,dcopt);slim_seconds=toc(t);slim_audit=audit_diagnostic_DCPF(prior,slim_dc);
    slim_if=npcc_nygrid_2025_slim_interfaces(slim_dc);archived_if=archive.interface_pf(h,:)';
    t=tic;full_dc=rundcpf(full,dcopt);full_seconds=toc(t);full_audit=audit_diagnostic_DCPF(full,full_dc);
    [full_if,full_weights]=physical_interface_flows(full_dc,(1:size(full.branch,1))',full);
    t=tic;detailed_dc=rundcpf(detailed,dcopt);detailed_dc_seconds=toc(t);detailed_dc_audit=audit_diagnostic_DCPF(detailed,detailed_dc);
    parents=detailed.userdata.ac_system.branch_parent_row;
    [detailed_dc_if,weights]=physical_interface_flows(detailed_dc,parents,full);
    t=tic;detailed_ac=runpf(detailed,acopt);detailed_ac_seconds=toc(t);[ac_audit,ac_detail]=audit_profile_pf(detailed,detailed_ac);
    detailed_ac_if=physical_interface_flows(detailed_ac,parents,full);
    gamma=archive.gamma;assert(gamma==prior.userdata.nygrid2025.scale_factor_gamma);
    a=struct('hour_index',h,'original_eight_hour_cohort',ismember(h,archive.primary_hours), ...
        'posthoc_diagnostic_extreme',ismember(h,archive.additional_diagnostic_extremes),'gamma',gamma, ...
        'input_seconds',input_seconds,'slim_DC_seconds',slim_seconds,'restored_parent_DC_seconds',full_seconds, ...
        'detailed_DC_seconds',detailed_dc_seconds,'detailed_AC_seconds',detailed_ac_seconds, ...
        'archived_vs_fresh_slim_DC_interface_max_MW',max(abs(archived_if-slim_if.model_mw)), ...
        'archived_vs_fresh_slim_angle_max_deg',max(abs(archive.bus_va(h,:)'-slim_dc.bus(:,9))), ...
        'archived_vs_full_parent_DC_interface_max_MW',max(abs(archived_if-full_if(:,1))), ...
        'slim_DC_audit_passed',slim_audit.passed,'full_parent_DC_audit_passed',full_audit.passed, ...
        'detailed_DC_audit_passed',detailed_dc_audit.passed,'detailed_AC_equation_gate',ac_audit.AC_equation_gate, ...
        'detailed_AC_profile_gate',ac_audit.P_profile_preservation_gate,'detailed_AC_VQ_assumption_gate',ac_audit.VQ_and_generator_assumption_gate, ...
        'CE_archived_DC_public_MW',archived_if(5)/gamma,'CE_fresh_slim_DC_public_MW',slim_if.model_mw(5)/gamma, ...
        'CE_restored_parent_DC_public_MW',full_if(5,1)/gamma,'CE_detailed_DC_public_MW',detailed_dc_if(5,1)/gamma, ...
        'CE_detailed_AC_public_MW',detailed_ac_if(5,1)/gamma, ...
        'CE_construction_delta_public_MW',(detailed_dc_if(5,1)-archived_if(5))/gamma, ...
        'CE_same_network_AC_minus_DC_public_MW',(detailed_ac_if(5,1)-detailed_dc_if(5,1))/gamma, ...
        'CE_total_AC_minus_archived_DC_public_MW',(detailed_ac_if(5,1)-archived_if(5))/gamma, ...
        'detailed_AC_losses_model_MW',ac_audit.AC_real_losses_mw,'detailed_AC_slack_increment_model_MW',ac_audit.reference_PG_change_MW, ...
        'detailed_AC_max_non_slack_PG_change_MW',ac_audit.maximum_non_slack_PG_change_MW,'passed',false);
    a.passed=a.slim_DC_audit_passed&&a.full_parent_DC_audit_passed&&a.detailed_DC_audit_passed ...
        &&a.detailed_AC_equation_gate&&a.detailed_AC_profile_gate ...
        &&max([a.archived_vs_fresh_slim_DC_interface_max_MW,a.archived_vs_full_parent_DC_interface_max_MW,a.archived_vs_fresh_slim_angle_max_deg])<1e-7;
    save(fullfile(out,sprintf('bridge_h%04d.mat',h)),'h','prior','full','detailed','slim_dc','full_dc','detailed_dc','detailed_ac', ...
        'archived_if','slim_if','full_if','detailed_dc_if','detailed_ac_if','weights','full_weights','slim_audit','full_audit','detailed_dc_audit','ac_audit','ac_detail','a','dcopt','acopt');
    checks=[checks a]; %#ok<AGROW>
    fprintf('CE_BRIDGE h%d pass%d parity%.3g CEarchive%.3f detailedDC%.3f AC%.3f construction%+.3f nonlinear%+.3f publicMW\n', ...
        h,a.passed,a.archived_vs_full_parent_DC_interface_max_MW,a.CE_archived_DC_public_MW,a.CE_detailed_DC_public_MW,a.CE_detailed_AC_public_MW,a.CE_construction_delta_public_MW,a.CE_same_network_AC_minus_DC_public_MW);
end
report=struct('completed',true,'passed',all([checks.passed]),'hours',hours,'primary_hours',archive.primary_hours, ...
    'additional_diagnostic_extremes',archive.additional_diagnostic_extremes,'elapsed_seconds',toc(start),'checks',checks, ...
    'stages',{{'archived_DC_bounded_x_nominal','fresh_slim148_DC_affine_operator','restored_full191_or192_DC_parent','fresh_DCPF_on_detailed_AC_network','fresh_ACPF_on_same_detailed_network'}}, ...
    'operator','unchanged_legacy_signed_literal_from_physical_parent_terminals','same_profiles_and_six_transfers',true, ...
    'OPF_or_parameter_fitting_used',false,'observed_interface_values_read_as_solver_input',false,'diagnostic_not_physical_requalification',true);
writetable(struct2table(checks),fullfile(out,'bridge_checks.csv'));
fid=fopen(fullfile(out,'bridge_receipt.json'),'w');fprintf(fid,'%s\n',jsonencode(report,'PrettyPrint',true));fclose(fid);
end
